import {useContext} from 'react'
import {graphql, useFragment} from 'react-relay'

import {CurrentUserKeyContext} from '../contexts/currentUserKey'

import type {useMyProfileFragment$key} from './__generated__/useMyProfileFragment.graphql'

const useMyProfileFragment = graphql`
  fragment useMyProfileFragment on User {
    name
    username
    email
  }
`

export default function useMyProfile() {
  const currentUserKey: useMyProfileFragment$key | null = useContext(CurrentUserKeyContext)
  return useFragment(useMyProfileFragment, currentUserKey)
}
