import {
  ControlsHeight,
  ControlsHeightContext,
} from '@jetbrains/ring-ui-built/components/global/controls-height'
import * as React from 'react'

import {useAppDispatch, useAppSelector} from '../../../../../../hooks/react-redux'
import Icon from '../../../../../common/Icon/Icon'
import {isTechInsightsPanelEnabled} from '../../../utils/featureToggles'
import {feedbackForm} from '../Feedback.slice'

import {useFeedbackFormModel} from './FeedbackForm.hooks'
import FeedbackFormComment from './FeedbackFormComment/FeedbackFormComment'
import FeedbackFormConsent from './FeedbackFormConsent/FeedbackFormConsent'
import FeedbackFormControls from './FeedbackFormControls/FeedbackFormControls'
import FeedbackFormRating from './FeedbackFormRating/FeedbackFormRating'
import TechInsightsPanel from './TechInsightsPanel/TechInsightsPanel'

import styles from './FeedbackForm.module.css'

type Props = {
  onDismiss?: () => void
}

function FeedbackForm({onDismiss}: Props) {
  const dispatch = useAppDispatch()
  const showCommentField = useAppSelector(
    state => state.pipelines.feedbackForm.misc.showCommentField,
  )

  const {sendResult, onSubmit, onDontShowAgain} = useFeedbackFormModel()
  const onRatingSelect = React.useCallback(
    (value: number) => dispatch(feedbackForm.actions.setRating(value)),
    [dispatch],
  )

  const onTypeText = React.useCallback(
    (text: string) => dispatch(feedbackForm.actions.setComment(text)),
    [dispatch],
  )

  return (
    <ControlsHeightContext.Provider value={ControlsHeight.M}>
      {sendResult.isSuccess ? (
        isTechInsightsPanelEnabled ? (
          <TechInsightsPanel />
        ) : (
          <div className={styles.success}>
            <Icon className={styles.checkmark} name="checkmark" />
            <div>{'Your feedback is sent!'}</div>
          </div>
        )
      ) : (
        <>
          <FeedbackFormRating onRatingSelect={onRatingSelect} />

          {showCommentField ? <FeedbackFormComment onTypeText={onTypeText} /> : null}
          <FeedbackFormConsent />
          <FeedbackFormControls
            loader={sendResult.isLoading}
            onSubmit={onSubmit}
            onDontShowAgain={() => {
              onDontShowAgain()
              onDismiss?.()
            }}
          />
          {sendResult.error ? (
            <div className={styles.error}>
              {(() => {
                if (sendResult.error && typeof sendResult.error === 'object') {
                  if ('data' in sendResult.error && typeof sendResult.error.data === 'string') {
                    return sendResult.error.data
                  }
                  if (
                    'message' in sendResult.error &&
                    typeof sendResult.error.message === 'string'
                  ) {
                    return sendResult.error.message
                  }
                  return 'An error occurred while submitting feedback'
                }
                return String(sendResult.error)
              })()}
            </div>
          ) : null}
        </>
      )}
    </ControlsHeightContext.Provider>
  )
}

export default React.memo(FeedbackForm)
