import * as dateFns from 'date-fns'
import {useState, useCallback} from 'react'

import {useUserTheme} from '../../../../../hooks/theme/useUserTheme'
import {useSetUserProperty} from '../../../../../hooks/useSetUserProperty'
import {trackEvent} from '../../../../../statistics/statistics.lazy'
import {UserProperties} from '../../../../../utils/userProperties'
import {isFeedbackCSATEnabled, isFeedbackCSATTestingEnabled} from '../../utils/featureToggles'

import {useShouldShowFeedbackForm} from './Feedback.hooks'
import FeedbackForm from './FeedbackForm/FeedbackForm'

import styles from './Feedback.module.css'

import ServiceMessage from 'src/components/common/ServiceMessage/ServiceMessage'

function Feedback() {
  const shouldShow = useShouldShowFeedbackForm()
  const [formClosed, setFormClosed] = useState<boolean>(false)
  const [hasTrackedDisplay, setHasTrackedDisplay] = useState<boolean>(false)
  const theme = useUserTheme()
  const setUserProperty = useSetUserProperty()

  if (shouldShow.visible && isFeedbackCSATEnabled && !hasTrackedDisplay && !formClosed) {
    trackEvent({
      groupId: 'feedback.csat.events.group',
      name: 'feedback.csat.form.display',
    })
    setHasTrackedDisplay(true)
  }

  const handleDismiss = useCallback(() => {
    const today = new Date()

    trackEvent({
      groupId: 'feedback.csat.events.group',
      name: 'feedback.csat.form.dismiss',
    })

    setUserProperty(UserProperties.FEEDBACK_LAST_DISMISSED_DATETIME, dateFns.formatISO(today))
    setFormClosed(true)
  }, [setUserProperty])

  return ((shouldShow.visible && isFeedbackCSATEnabled) || isFeedbackCSATTestingEnabled) &&
    !formClosed ? (
    <ServiceMessage
      closeable
      onClose={handleDismiss}
      theme={theme}
      containerClassName={styles.container}
      captionClassName={styles.caption}
      descriptionClassName={styles.description}
    >
      <FeedbackForm onDismiss={handleDismiss} />
    </ServiceMessage>
  ) : null
}

export default Feedback
