import * as dateFns from 'date-fns'
import {useCallback} from 'react'

import {useAppDispatch, useAppSelector} from '../../../../../../hooks/react-redux'
import {useSetUserProperty} from '../../../../../../hooks/useSetUserProperty'
import {useUserProperty} from '../../../../../../hooks/useUserProperty'
import {restApi} from '../../../../../../services/rest'
import {trackEvent} from '../../../../../../statistics/statistics.lazy'
import {UserProperties} from '../../../../../../utils/userProperties'
import {feedbackForm} from '../Feedback.slice'

export function useFeedbackFormModel() {
  const dispatch = useAppDispatch()
  const rating = useAppSelector(state => state.pipelines.feedbackForm.userInput.rating)
  const consent = useAppSelector(state => state.pipelines.feedbackForm.userInput.emailConsent)
  const email = useAppSelector(state => state.pipelines.feedbackForm.userInput.email)

  const comment = useAppSelector(state => state.pipelines.feedbackForm.userInput.comment)
  const lastDismissedDateTime = useUserProperty(UserProperties.FEEDBACK_LAST_DISMISSED_DATETIME)

  const setUserProperty = useSetUserProperty()
  const [send, sendResult] = restApi.endpoints.sendFeedback.useMutation()

  const onSubmit = useCallback(() => {
    const today = new Date()
    const isRecurringSubmission = !!lastDismissedDateTime

    trackEvent({
      groupId: 'feedback.csat.events.group',
      name: isRecurringSubmission
        ? 'feedback.csat.form.submit.after.dismiss'
        : 'feedback.csat.form.submit',
    })

    send({feedback: comment, consent, email, rating})

    setUserProperty(UserProperties.FEEDBACK_LAST_SUBMITTED_DATETIME, dateFns.formatISO(today))
  }, [lastDismissedDateTime, send, comment, consent, email, rating, setUserProperty])

  const onDontShowAgain = useCallback(() => {
    trackEvent({
      groupId: 'feedback.csat.events.group',
      name: 'feedback.csat.form.dont.show.again',
    })

    setUserProperty(UserProperties.NEVER_SHOW_FEEDBACK_FORM, 'true')

    dispatch(feedbackForm.actions.setVisibility({visible: false}))
  }, [dispatch, setUserProperty])

  return {
    sendResult,
    onSubmit,
    onDontShowAgain,
  }
}
