import infoIcon from '@jetbrains/icons/info-12px'
import Checkbox from '@jetbrains/ring-ui-built/components/checkbox/checkbox'
import Icon from '@jetbrains/ring-ui-built/components/icon'
import Input, {Size} from '@jetbrains/ring-ui-built/components/input/input'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import {type ChangeEvent, useEffect, useState} from 'react'

import {useAppDispatch, useAppSelector} from '../../../../../../../hooks/react-redux'
import useMyProfile from '../../../../../../../hooks/useMyProfile'
import {feedbackForm} from '../../Feedback.slice'

import styles from './FeedbackFormConsent.module.css'

const THIRD_PARTY_SERVICES_LINK = 'https://www.jetbrains.com/legal/privacy/third-parties.html'
const PRIVACY_POLICY_LINK = 'https://www.jetbrains.com/company/privacy.html'

export const validateEmail = (email: string): string | null => {
  if (email.trim().length === 0) {
    return 'Email is required'
  } else if (!email.includes('@')) {
    return 'Email needs to contain @'
  }
  return null
}
function FeedbackFormConsent() {
  const dispatch = useAppDispatch()
  const consent = useAppSelector(state => state.pipelines.feedbackForm.userInput.emailConsent)
  const email = useAppSelector(state => state.pipelines.feedbackForm.userInput.email)
  const user = useMyProfile()

  const userEmail = user?.email ?? ''
  const [error, setError] = useState<string | null>(null)

  const [emailValue, setEmailValue] = useState(email || userEmail)

  const handleConsentChange = () => {
    const newConsent = !consent
    dispatch(feedbackForm.actions.setEmailConsent(newConsent))

    if (newConsent && !email) {
      dispatch(feedbackForm.actions.setEmail(userEmail))
    }
  }

  const handleEmailChange = ({currentTarget: {value}}: ChangeEvent<HTMLInputElement>) => {
    setEmailValue(value)
    dispatch(feedbackForm.actions.setEmail(value))
  }

  useEffect(() => {
    if (consent) {
      setError(validateEmail(emailValue))
    } else {
      setError(null)
    }
  }, [consent, emailValue])

  return (
    <div className={styles.consent}>
      <div>
        <Checkbox
          label={'I agree to be contacted by JetBrains via email '}
          checked={consent}
          onChange={handleConsentChange}
        />
      </div>
      <div className={styles.emailField}>
        <Input
          multiline={false}
          value={emailValue}
          disabled={!consent}
          size={Size.FULL}
          onChange={handleEmailChange}
          error={error}
        />
      </div>
      <div className={styles.consentText}>
        {'By submitting this form, I agree to share '}
        <Link>
          <Tooltip
            title="Version of your TeamCity, if your TeamCity is JetBrains hosted, license type, license ID hash, your permissions group - whether you can view or run builds, edit project or server settings; number of your favourite projects, build configurations, and pipelines; list of build features and runners used in your favourite projects."
            popupProps={{
              className: styles.tooltip,
            }}
          >
            <>
              {'system information '}
              <Icon glyph={infoIcon} />
            </>
          </Tooltip>
        </Link>
        {'. I agree that JetBrains s.r.o. may process said data using '}
        <Link href={THIRD_PARTY_SERVICES_LINK} target={'_blank'} rel="noreferrer">
          {'third-party services'}
        </Link>
        {' for this purpose in accordance with the '}
        <Link href={PRIVACY_POLICY_LINK} target={'_blank'} rel="noreferrer">
          {'JetBrains Privacy Policy.'}
        </Link>
      </div>
    </div>
  )
}

export default FeedbackFormConsent
