import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonGroup from '@jetbrains/ring-ui-built/components/button-group/button-group'
import type {MouseEvent} from 'react'
import * as React from 'react'

import FeedbackFormSection from '../FeedbackFormSection/FeedbackFormSection'

import dissatisfied from './dissatisfied-16px.svg'
import neutral from './neutral-16px.svg'
import satisfied from './satisfied-16px.svg'
import veryDissatisfied from './very_dissatisfied-16px.svg'
import verySatisfied from './very_satisfied-16px.svg'

import styles from './FeedbackFormRating.module.css'

type Props = {
  onRatingSelect: (rating: number) => void
}

const ratings = {
  1: {icon: veryDissatisfied, alt: 'Very dissatisfied'},
  2: {icon: dissatisfied, alt: 'Dissatisfied'},
  3: {icon: neutral, alt: 'Neutral'},
  4: {icon: satisfied, alt: 'Satisfied'},
  5: {icon: verySatisfied, alt: 'Very satisfied'},
}

function FeedbackFormRating({onRatingSelect}: Props) {
  const [rating, setLocalRating] = React.useState(0)
  const setRating = React.useCallback(
    (event: MouseEvent<HTMLButtonElement>) => {
      const value = parseInt(event.currentTarget?.dataset?.value || '0', 10)
      setLocalRating(value)

      onRatingSelect(value)
    },
    [onRatingSelect],
  )

  return (
    <FeedbackFormSection
      title={<>{'Tell us about your experience'}</>}
      text={'How satisfied are you with the product?'}
    >
      <div className={styles.valuesContainer}>
        <ButtonGroup className={styles.values}>
          {Object.entries(ratings).map(([v, {icon, alt}]) => {
            const value = parseInt(v, 10)
            return (
              <Button
                key={value}
                onClick={setRating}
                data-value={value}
                active={rating === value}
                className={styles.value}
              >
                <img alt={alt} src={icon} width={16} height={16} />
              </Button>
            )
          })}
        </ButtonGroup>
        <div className={styles.hints}>
          <span className={styles.hint}>{'Very dissatisfied'}</span>
          <span className={styles.hint}>{'Neutral'}</span>
          <span className={styles.hint}>{'Very satisfied'}</span>
        </div>
      </div>
    </FeedbackFormSection>
  )
}

export default React.memo(FeedbackFormRating)
