import * as dateFns from 'date-fns'
import {useEffect, useMemo} from 'react'

import {useAppDispatch, useAppSelector} from '../../../../../hooks/react-redux'
import {useQueryParams} from '../../../../../hooks/routes'
import useMyProfile from '../../../../../hooks/useMyProfile'
import {useSetUserProperty} from '../../../../../hooks/useSetUserProperty'
import {useUserProperty, useBooleanUserProperty} from '../../../../../hooks/useUserProperty'
import {UserProperties} from '../../../../../utils/userProperties'

import {feedbackForm} from './Feedback.slice'

const TWO_WEEKS = 2
const THREE_MONTHS = 3
const GUEST_USER_NAME = 'Guest user'
const SUPER_USER_NAME = 'Super user'

const useShouldShowFeedbackForm = () => {
  const dispatch = useAppDispatch()
  const queryParams = useQueryParams()

  const user = useMyProfile()

  const today = useMemo(() => new Date(), [])

  const registrationDateTime = useUserProperty(UserProperties.FEEDBACK_REGISTRATION_DATETIME)
  const lastSubmittedDateTime = useUserProperty(UserProperties.FEEDBACK_LAST_SUBMITTED_DATETIME)
  const lastDismissedDateTime = useUserProperty(UserProperties.FEEDBACK_LAST_DISMISSED_DATETIME)
  const neverShowFeedbackForm = useBooleanUserProperty(UserProperties.NEVER_SHOW_FEEDBACK_FORM)
  const setUserProperty = useSetUserProperty()

  const parsedRegistration = dateFns.parseISO(registrationDateTime ?? '')
  const isInvalidRegistration =
    parsedRegistration instanceof Date && isNaN(parsedRegistration.getMilliseconds())
  const registration = isInvalidRegistration ? today : parsedRegistration

  useEffect(() => {
    if (isInvalidRegistration) {
      setUserProperty(UserProperties.FEEDBACK_REGISTRATION_DATETIME, dateFns.formatISO(today))
    }
  }, [isInvalidRegistration, setUserProperty, registrationDateTime, today])

  const lastSubmitted = useMemo(
    () => dateFns.parseISO(lastSubmittedDateTime ?? ''),
    [lastSubmittedDateTime],
  )

  const lastDismissed = useMemo(
    () => dateFns.parseISO(lastDismissedDateTime ?? ''),
    [lastDismissedDateTime],
  )

  const isOnBuildLogTab = queryParams.buildTab === 'log'

  const shouldShowFeedback = useMemo(() => {
    if (user?.name === GUEST_USER_NAME || user?.name === SUPER_USER_NAME) {
      return false
    }
    const weeksFromRegistration = dateFns.differenceInWeeks(today, registration)
    const monthsFromLastSubmission = lastSubmittedDateTime
      ? dateFns.differenceInMonths(today, lastSubmitted)
      : Infinity

    if (lastDismissedDateTime) {
      const weeksFromLastDismissal = dateFns.differenceInWeeks(today, lastDismissed)
      const monthsFromLastDismissal = dateFns.differenceInMonths(today, lastDismissed)

      if (lastSubmittedDateTime) {
        if (monthsFromLastDismissal < THREE_MONTHS) {
          return false
        }
      } else if (weeksFromLastDismissal < TWO_WEEKS) {
        return false
      }
    }

    const shouldShowInitial = !lastSubmittedDateTime && weeksFromRegistration >= TWO_WEEKS
    const shouldShowRecurring = lastSubmittedDateTime && monthsFromLastSubmission >= THREE_MONTHS

    return shouldShowInitial || shouldShowRecurring
  }, [
    user?.name,
    today,
    registration,
    lastSubmittedDateTime,
    lastSubmitted,
    lastDismissedDateTime,
    lastDismissed,
  ])

  useEffect(() => {
    if (shouldShowFeedback && !neverShowFeedbackForm && !isOnBuildLogTab) {
      dispatch(
        feedbackForm.actions.setVisibility({
          visible: true,
        }),
      )
    }
  }, [dispatch, shouldShowFeedback, queryParams.buildTab, neverShowFeedbackForm, isOnBuildLogTab])

  return useAppSelector(state => state.pipelines.feedbackForm.visibility)
}

export {useShouldShowFeedbackForm}
