import Input from '@jetbrains/ring-ui-built/components/input/input'
import type {ChangeEvent} from 'react'
import * as React from 'react'
import {useId} from 'react'

import {useAppSelector} from '../../../../../../../hooks/react-redux'
import FeedbackFormSection from '../FeedbackFormSection/FeedbackFormSection'

import styles from './FeedbackFormComment.module.css'

function FeedbackFormComment({onTypeText}: {onTypeText: (text: string) => void}) {
  const textAreaRef = React.useRef<HTMLTextAreaElement>(null)
  const comment = useAppSelector(state => state.pipelines.feedbackForm.userInput.comment)

  const updateComment = React.useCallback(
    (event: ChangeEvent<HTMLTextAreaElement>) => {
      onTypeText(event.target.value)
    },
    [onTypeText],
  )

  React.useEffect(() => {
    textAreaRef.current?.focus()
  }, [])

  const id = useId()

  return (
    <FeedbackFormSection className={styles.section}>
      <label htmlFor={id} className={styles.hint}>
        {'Please elaborate on your choice (Optional):'}
      </label>
      <Input
        multiline
        autogrow={false}
        id={id}
        inputRef={textAreaRef}
        onChange={updateComment}
        value={comment}
        rows={5}
        className={styles.textareaContainer}
        inputClassName={styles.textarea}
      />
    </FeedbackFormSection>
  )
}

export default React.memo(FeedbackFormComment)
