import Button from '@jetbrains/ring-ui-built/components/button/button'
import Link from '@jetbrains/ring-ui-built/components/link/link'

import {useAppSelector} from '../../../../../../../hooks/react-redux'
import {validateEmail} from '../FeedbackFormConsent/FeedbackFormConsent'

import styles from './FeedbackFormControls.module.css'

type Props = {
  onSubmit: () => void
  loader?: boolean
  onDontShowAgain?: () => void
}

function FeedbackFormControls({onSubmit, onDontShowAgain, loader}: Props) {
  const {rating, emailConsent, email} = useAppSelector(
    state => state.pipelines.feedbackForm.userInput,
  )

  const canSubmit = rating !== 0 && (!emailConsent || validateEmail(email) == null)
  return (
    <div className={styles.controls}>
      <Button
        disabled={!canSubmit}
        primary
        loader={loader}
        onClick={onSubmit}
        className={styles.submit}
      >
        {'Submit'}
      </Button>
      <Link onClick={onDontShowAgain}>{"Don't show again"}</Link>
    </div>
  )
}
export default FeedbackFormControls
